export const POPULAR_SITE_BY_HOST: Record<string, PopularSite> = Object.fromEntries(POPULAR_SITES.map(site => [site.host.replace(/^www\./, ""), site]));
export function popularSiteFor(host: string): PopularSite | undefined {
 const normal=host.toLowerCase().replace(/^www\./, "");
 return POPULAR_SITE_BY_HOST[normal] || POPULAR_SITES.find(site => site.host.replace(/^www\./, "") === normal);
}
